async function syncTaskDetail(){
 const id=visibleTaskId(),version=navigationVersion,request=++taskDetailRequest;
 activeTaskDetail=null;
 const task=state.tasks.find(t=>String(t.id)===String(id));
 if(!task?.localContext){settledTaskDetail=null;return;}
 // A settled, still-visible task whose aggregate summary is unchanged keeps its
 // verified detail; a summary/status change, task switch or active task refetches.
 const summary=JSON.stringify(task);
 if(settledTaskDetail?.summary===summary&&String(settledTaskDetail.detail.id)===String(id)){activeTaskDetail=settledTaskDetail.detail;return;}
 try{const detail=await api('/api/tasks/'+encodeURIComponent(id));
  if(request===taskDetailRequest&&version===navigationVersion&&String(id)===String(visibleTaskId())&&detail.id===task.id){activeTaskDetail=detail;settledTaskDetail=settledDetailStatus.has(task.status)&&settledDetailStatus.has(detail.status)?{summary,detail}:null;}
 }catch{ /* Keep the safe aggregate placeholder when detail is unavailable. */ }
}
