async function api(path, options={}){
 const controller=new AbortController();const {timeoutMs=20000,...fetchOptions}=options;const timeout=setTimeout(()=>controller.abort(),timeoutMs);
 try{const res=await fetch(path,{...fetchOptions,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:controller.signal});let body={};try{body=await res.json();}catch{if(!res.ok)throw new Error(`服务返回 ${res.status}`);}if(!res.ok){const failure=new Error(body.error||`请求失败（${res.status}）`);if(typeof body.code==='string'&&/^[A-Z_0-9]{1,80}$/.test(body.code))failure.code=body.code;throw failure;}return body;}catch(err){if(err.name==='AbortError')throw new Error('请求等待超时；操作可能仍在进行，请查看最新状态，勿重复提交');throw err;}finally{clearTimeout(timeout);}
}
