function inlineMarkdown(text){
 const pattern=/(`[^`\n]+`|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\([^\s)]+\))/g;let html='',last=0;
 for(const match of text.matchAll(pattern)){html+=esc(text.slice(last,match.index));const token=match[0];
  if(token.startsWith('`'))html+='<code>'+esc(token.slice(1,-1))+'</code>';
  else if(token.startsWith('**'))html+='<strong>'+esc(token.slice(2,-2))+'</strong>';
  else{const parts=token.match(/^\[([^\]]+)\]\((.+)\)$/);let valid=false;try{const url=new URL(parts[2]);valid=['https:','http:'].includes(url.protocol)&&!url.username&&!url.password;}catch{}html+=valid?'<a href="'+esc(parts[2])+'" target="_blank" rel="noopener noreferrer">'+esc(parts[1])+'</a>':esc(token);}
  last=match.index+token.length;
 }return html+esc(text.slice(last));
}
function formatOutput(value){
 const lines=str(value).replace(/\r\n?/g,'\n').split('\n');let html='',paragraph=[],list='',code=null;
 const flush=()=>{if(paragraph.length){html+=paragraph.map(inlineMarkdown).join('\n');paragraph=[];}if(list){html+='</'+list+'>';list='';}};
 for(const line of lines){if(line.startsWith('```')){flush();if(code===null)code=[];else{html+='<pre><code>'+esc(code.join('\n'))+'</code></pre>';code=null;}continue;}if(code!==null){code.push(line);continue;}
  const heading=line.match(/^(#{1,3})\s+(.+)$/),item=line.match(/^\s*(?:([-*])|([0-9]+)[.)])\s+(.+)$/);
  if(!line.trim()){flush();html+='\n';continue;}if(heading){flush();html+='<h'+Math.min(3,heading[1].length+1)+'>'+inlineMarkdown(heading[2])+'</h'+Math.min(3,heading[1].length+1)+'>';}
  else if(item){if(paragraph.length)flush();const kind=item[1]?'ul':'ol';if(list!==kind){flush();html+='<'+kind+'>';list=kind;}html+='<li>'+inlineMarkdown(item[3])+'</li>';}
  else{if(list)flush();paragraph.push(line);}
 }flush();if(code!==null)html+='<pre><code>'+esc(code.join('\n'))+'</code></pre>';return html;
}
