// STABLE-DOM: idle polls write nothing; a same-view chat refresh patches the
// mounted nodes in place, so .home-main keeps its one entry animation and the
// composer keeps its node, draft, focus, selection, IME composition and scroll.
const chromeWritten=new WeakMap();
function chromeHTML(el,html){if(el&&chromeWritten.get(el)!==html){el.innerHTML=html;chromeWritten.set(el,html);}}
