// SELECTION: text is patched with insertData/deleteData of only the changed span, so a
// live Range (the user's selected answer text) keeps its endpoints under the DOM
// "replace data" rules instead of collapsing to 0. If the pending patch of a task answer
// would still move or change what is selected, only that answer region is held - and
// only while the new answer still contains everything shown - and it catches up when
// the selection leaves it (selectionchange) or on the next poll. Approvals, permissions and runtime clears are never held.
let heldSelection=null;
function patchText(node,value){
 const old=node.data,max=Math.min(old.length,value.length);let p=0,s=0;
 while(p<max&&old.charCodeAt(p)===value.charCodeAt(p))p++;
 while(s<max-p&&old.charCodeAt(old.length-1-s)===value.charCodeAt(value.length-1-s))s++;
 const inserted=value.slice(p,value.length-s),removed=old.length-p-s;
 if(inserted)node.insertData(p,inserted);
 if(removed)node.deleteData(p+inserted.length,removed);
}
function holdSelection(live,next){
 const selection=document.getSelection?.(),range=selection?.rangeCount&&!selection.isCollapsed?selection.getRangeAt(0):null;
 if(!range||!range.intersectsNode(live))return false;
 const plain=text=>text.replace(/[\s#*]+/g,'');
 if(!plain(next.textContent).startsWith(plain(live.textContent)))return false;
 // Replay the exact patch on detached copies with the selection clipped to the region.
 const copy=live.cloneNode(true),wrap=document.createElement('div'),trial=document.createRange();wrap.appendChild(copy);
 const locate=node=>{const steps=[];for(let n=node;n!==live;n=n.parentNode)steps.unshift([...n.parentNode.childNodes].indexOf(n));return steps.reduce((n,i)=>n.childNodes[i],copy);};
 if(live.contains(range.startContainer))trial.setStart(locate(range.startContainer),range.startOffset);else trial.setStart(wrap,0);
 if(live.contains(range.endContainer))trial.setEnd(locate(range.endContainer),range.endOffset);else trial.setEnd(wrap,1);
 const selected=trial.toString();morphChildren(copy,next.cloneNode(true));
 if(!trial.collapsed&&trial.toString()===selected)return false;
 // What is shown no longer matches the last rendered signature: the next poll re-renders.
 heldSelection=live;lastSignature='';return true;
}
function morphNode(live,next){
 if(live.nodeType!==1){if(live.nodeValue!==next.nodeValue){if(live.nodeType===3)patchText(live,next.nodeValue);else live.nodeValue=next.nodeValue;}return;}
 if(live.hasAttribute('data-selection-hold')&&next.hasAttribute('data-selection-hold')&&holdSelection(live,next))return;
 for(const {name} of [...live.attributes])if(!next.hasAttribute(name))live.removeAttribute(name);
 for(const {name,value} of [...next.attributes])if(live.getAttribute(name)!==value)live.setAttribute(name,value);
 if(live.tagName==='TEXTAREA'){if(live.id==='prompt-input'&&live.value!==draft&&!(promptComposing&&live===document.activeElement))live.value=draft;return;}
 morphChildren(live,next);
}
function morphChildren(live,next){
 const incoming=[...next.childNodes],wanted=new Set(incoming.map(domKey).filter(Boolean)),keyed=new Map();
 for(const child of live.childNodes){const key=domKey(child);if(key)keyed.set(key,child);}
 let cursor=live.firstChild;
 for(const node of incoming){
  while(cursor&&domKey(cursor)&&!wanted.has(domKey(cursor))){const stale=cursor;cursor=cursor.nextSibling;live.removeChild(stale);}
  const key=domKey(node),match=key?keyed.get(key):cursor&&!domKey(cursor)&&cursor.nodeName===node.nodeName?cursor:null;
  if(match&&match.nodeName===node.nodeName){if(key)keyed.delete(key);
   // A keyed node ahead of the cursor stays in place (moving it would drop a selection
   // inside it) when everything before it is unkeyed or no longer wanted.
   let gap=cursor;while(gap&&gap!==match&&!(domKey(gap)&&wanted.has(domKey(gap))))gap=gap.nextSibling;
   if(gap===match)while(cursor!==match){const stale=cursor;cursor=cursor.nextSibling;live.removeChild(stale);}
   if(match===cursor)cursor=cursor.nextSibling;else live.insertBefore(match,cursor);morphNode(match,node);}
  else live.insertBefore(node,cursor);
 }
 while(cursor){const stale=cursor;cursor=cursor.nextSibling;live.removeChild(stale);}
}
function render(force=false){
 renderChrome();
 if(main.dataset.view!==view)main.dataset.view=view;
 if(!loaded){if(!online){main.innerHTML=`<div class="error-page">${icon('link')}<h2>工作空间暂未连接</h2><p>请确认本地服务已启动。连接恢复后，任务与设置会自动重新加载。</p><button class="secondary-button" data-action="refresh">${icon('refresh')}重新连接</button></div>`;mainMount='';}return;}
 if(!force&&view==='settings'&&$('#settings-form'))return;
 const mount=view+':'+navigationVersion,stable=view==='chat'&&mainMount===mount;
 if(!stable&&!force&&document.activeElement&&main.contains(document.activeElement)&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){pendingRender=true;return;}
 pendingRender=false;
 const html=({chat:renderHome,tasks:renderTasks,schedules:renderSchedules,agents:renderAgents,knowledge:renderKnowledge,mail:renderMail,browser:renderControlled,audit:renderAudit,settings:renderSettings}[view])();
 const threadBefore=$('.chat-thread'),scrollBefore=threadBefore?.scrollTop||0,followBottom=threadBefore&&threadBefore.scrollHeight-threadBefore.clientHeight-scrollBefore<48&&!document.getSelection?.()?.toString();
 const markup=(!online?'<div class="connection-banner" data-key="connection-banner">连接已中断，当前显示最近一次读取的数据。服务恢复后将自动同步。</div>':'')+html;
 if(stable){const template=document.createElement('template');template.innerHTML=markup;heldSelection=null;morphChildren(main,template.content);}
 else{const threadScroll=$('.chat-thread')?.scrollTop||0;main.innerHTML=markup;mainMount=mount;promptComposing=false;heldSelection=null;if($('.chat-thread'))$('.chat-thread').scrollTop=threadScroll;}
 if(view==='chat'){const thread=$('.chat-thread');if(thread)thread.scrollTop=followBottom?thread.scrollHeight:scrollBefore;syncComposerButton();}
 applyBusyButtons();
 if(view==='settings'){applySettingsToForm($('#settings-form'));syncUpdatePanel();void pollDesktopUpdate();}
}
function chosenAgent(){return getAgent(draftAgent||taskById(chatTaskId)?.agentId||'coordinator')||state.agents.find(a=>a.enabled!==false);}
function modelReady(){const a=chosenAgent();return state.settings?.mode==='api'&&!!(a?.modelConfig?.inherit===false?a.hasApiKey&&a.modelConfig.model:state.settings.hasApiKey&&state.settings.model);}
function composerModel(){const a=chosenAgent();return a?.modelConfig?.inherit===false?a.modelConfig.model:state.settings?.model;}
function syncComposerButton(){const button=$('#task-form button[type="submit"]');if(button)button.disabled=submitting||!draft.trim()||!modelReady()||!online||taskActive(taskById(chatTaskId)||{});}
function renderComposer(hasTask=false){return `<form class="composer" id="task-form" data-key="composer"><textarea id="prompt-input" name="prompt" aria-label="任务描述" placeholder="${hasTask?'继续这个对话…':'问问路衡，或描述想完成的事…'}" required maxlength="12000">${esc(draft)}</textarea><div class="composer-tools"><div class="composer-meta"><button type="button" class="composer-tools-toggle" data-action="capabilities" aria-label="工具、附件与 Skills">${icon('plus')}<span>工具</span></button><button type="button" class="composer-options-toggle" data-action="toggle-options" aria-expanded="${optionsOpen}" aria-controls="composer-options">${icon('agents')}<span>${esc(chosenAgent()?.name||'通用助手')}</span>${icon('chevron')}</button><button type="button" class="composer-skill-button ${selectedSkills.length?'selected':''}" data-action="skills">Skills${selectedSkills.length?' '+selectedSkills.length:''}</button><div class="composer-options" id="composer-options" ${optionsOpen?'':'hidden'}><label class="agent-select">${icon('agents')}<select name="agentId" id="agent-select" aria-label="选择执行智能体">${agentOptions(draftAgent)}</select></label><span class="composer-budget">执行上限 ${esc(state.settings.budget||20)} 次</span>${renderLocalAccessSelector()}<button type="button" class="text-link" data-nav="settings">模型与高级设置 ↗</button></div></div><div class="composer-send"><button type="button" class="composer-model" data-nav="settings" title="配置模型服务">${icon('spark')}<span>${esc(composerModel()||'连接模型')}</span></button><button class="send-button ${submitting?'loading-button':''}" aria-label="开始执行任务" title="Ctrl / ⌘ Enter 发送" type="submit" ${submitting||!draft.trim()||!modelReady()||!online||taskActive(taskById(chatTaskId)||{})?'disabled':''}>${submitting?'<span class="spinner"></span>':icon('send')}</button></div></div></form><p class="composer-note" data-key="composer-note">${modelReady()?'任务与所选 Skills 会发送至已配置模型；重要操作仍需确认。':'先连接模型，再开始对话。'}<button class="text-link" data-nav="settings">${modelReady()?'设置':'配置模型'}</button></p>`;}
function conversationTurns(){const turns=[],seen=new Set();let current=taskById(chatTaskId);if(current){chatTurnCache.set(current.id,current);while(current&&!seen.has(current.id)&&turns.length<12){seen.add(current.id);turns.unshift(current);current=current.previousTaskId?(chatTurnCache.get(current.previousTaskId)||state.tasks.find(task=>task.id===current.previousTaskId)):null;}}return turns;}
function renderHome(){
 const turns=conversationTurns(),localCards=renderLocalConversation(),conversation=!!turns.length||!!localCards;
 return `<div class="home-toolbar" data-key="home-toolbar"><span class="workspace-caption">${turns.length?esc(turns[0].title||'对话'):'新对话'}</span><div class="button-row"><button class="overview-toggle" data-action="capabilities">${icon('panel')}工具与能力</button><button class="icon-button" data-action="new-task" aria-label="新建对话">${icon('plus')}</button></div></div><div class="home-grid ${conversation?'has-conversation':''}" data-key="home-grid"><section class="home-main" data-key="home-main"><div class="chat-thread" data-key="chat-thread" tabindex="0" aria-label="对话消息">${conversation?turns.map(renderTaskDetail).join('')+localCards:`<div class="welcome" data-key="welcome"><span class="welcome-logo"><img src="/agent-mark.svg" alt=""></span><h1>有什么想一起完成的？</h1><p>从一句话开始，用你选择的 Skills 定义工作方式。</p>${!modelReady()?'<button class="secondary-button" data-nav="settings">连接你的模型</button>':''}</div>`}</div>${renderComposer(conversation)}</section></div>`;
}
function renderCapabilities(){const capabilities=state.capabilities;return `<p class="modal-subtitle">当前角色：${esc(chosenAgent()?.name||'通用助手')}。这里显示服务返回的真实能力状态；可用工具仍受任务预算与操作审批约束。</p>${capabilityLoading?'<p class="compact-empty"><span class="spinner"></span>正在读取能力状态…</p>':capabilityError?`<p class="permission-warning">${esc(capabilityError)}</p>`:''}<div class="capability-list">${array(capabilities?.tools).map(tool=>`<article class="capability-row"><div><strong>${esc(tool.label||tool.name)}</strong><small>${esc(tool.name)}</small><p>${esc(tool.reason||tool.dependencies?.reason||tool.permission?.reason||'按配置与授权使用')}</p><small>网络：${esc({unknown:'尚未检测',reachable:'最近检测可达',unreachable:'最近检测不可达'}[tool.network?.status]||'不需要网络')}${tool.network?.serviceStatus==='unavailable'?'；最近调用服务暂不可用（'+esc(tool.network.code||'未知原因')+'）':''}</small></div><span class="capability-status ${esc(tool.status)}">${esc({available:'可用',unconfigured:'未配置',restricted:'权限受限',unimplemented:'未实现'}[tool.status]||'状态未知')}</span></article>`).join('')||(!capabilityLoading?'<p class="compact-empty">服务尚未提供能力清单，无法判定工具是否可用。</p>':'')}</div><div class="capability-row"><div><strong>用户 Skills</strong><p>导入后自行选择；不会自动执行脚本、安装依赖或扩大权限。</p></div><button class="secondary-button" data-action="skills">管理 Skills</button></div><div class="capability-row"><div><strong>附件</strong><p>当前支持 SKILL.md 文本包导入和知识文本添加；任意附件解析尚未实现。</p></div><button class="secondary-button" data-action="add-memory">添加知识</button></div><div class="button-row"><button class="secondary-button" data-nav="settings">配置模型与权限</button><button class="secondary-button" data-nav="browser">网页目标</button><button class="secondary-button" data-nav="mail">邮件账户</button></div>`;}
function renderSkills(){return `<p class="modal-subtitle">为当前对话选择最多4个 Skills。发送时正文会提供给所选模型；Skills 只定义方法，不授予额外工具权限。新对话默认不启用。</p><div class="skill-import"><label class="secondary-button" for="skill-file">${icon('plus')}导入 SKILL.md<input id="skill-file" type="file" accept=".md" hidden ${skillsImporting?'disabled':''}></label><label class="secondary-button" for="skill-package">导入文本包<input id="skill-package" type="file" webkitdirectory multiple hidden ${skillsImporting?'disabled':''}></label><small>根目录 SKILL.md 须含单行 name / description 头部；只读文本，最多24个文件 / 256KB，不导入脚本。</small></div><div class="skills-list">${array(state.skills).map(skill=>`<article class="skill-row"><label><input type="checkbox" data-skill-id="${esc(skill.id)}" ${selectedSkills.includes(skill.id)?'checked':''}><span><strong>${esc(skill.name)}</strong><p>${esc(skill.description)}</p><small>${skill.fileCount} 个文本文件 · 只读</small></span></label><button class="text-link" data-action="view-skill" data-id="${esc(skill.id)}">查看</button></article>`).join('')||'<div class="compact-empty">还没有 Skills。导入你自己的工作方法，再选择是否在会话中启用。</div>'}</div><div class="form-actions"><button class="primary-button" data-action="close-modal">完成选择</button></div>`;}
async function importSkillFiles(list){if(skillsImporting)return;skillsImporting=true;try{const files=[...list];if(!files.length)return;if(files.length>24)throw new Error('文本包最多24个文件');let total=0;const contents=[];for(const file of files){total+=file.size;if(file.size>65536||total>262144)throw new Error('每个文本最多64KB，文本包最多256KB');const relative=file.webkitRelativePath?file.webkitRelativePath.split('/').slice(1).join('/'):file.name;if(!/\.(md|txt|json|ya?ml|csv)$/i.test(relative))throw new Error('只支持文本包，不导入脚本或二进制文件');const bytes=await file.arrayBuffer();const content=new TextDecoder('utf-8',{fatal:true}).decode(bytes);contents.push({path:relative,content});}await post('/api/skills/import',{files:contents});await loadState();if(modal?.kind==='skills')openModal('skills');toast('Skill 已导入，请自行勾选启用');}catch(err){toast(err.message||'Skill 导入失败',true);}finally{skillsImporting=false;for(const input of document.querySelectorAll('#skill-file,#skill-package'))input.disabled=false;}}
async function showCapabilities(){capabilityLoading=true;capabilityError='';state.capabilities=null;openModal('capabilities');try{state.capabilities=await api('/api/tools/capabilities?agentId='+encodeURIComponent(chosenAgent()?.id||'coordinator'));}catch(err){capabilityError='能力状态读取失败：'+err.message;}finally{capabilityLoading=false;if(modal?.kind==='capabilities')openModal('capabilities');}}

function agentOptions(selected){const agents=state.agents.filter(a=>a.enabled!==false);return `<option value="">自动选择助手</option>`+agents.map(a=>`<option value="${esc(a.id)}" ${String(a.id)===String(selected)?'selected':''}>${esc(a.name)}</option>`).join('');}
function pageHeading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(iconName,title,description,action=''){return `<div class="empty-state">${icon(iconName)}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function renderTasks(){
 let tasks=state.tasks.filter(t=>taskFilter==='all'||taskFilter==='active'&&taskActive(t)||taskFilter==='done'&&taskDone(t)||taskFilter==='issues'&&['failed','cancelled','canceled','error','rejected','needs_attention'].includes(t.status));if(search)tasks=tasks.filter(t=>(t.title+' '+t.prompt).toLowerCase().includes(search.toLowerCase()));
 if(!selectedTaskId&&tasks.length)selectedTaskId=tasks[0].id;const selected=getTask();
 return pageHeading('TASK CENTER','每一件事，都有着落','从开始执行到最终交付，查看执行进度与交付文件；本机上下文的详细内容仅保留本次运行。',`<button class="primary-button" data-action="new-task">${icon('plus')}新任务</button>`)+
 `<div class="view-toolbar"><div class="tabs">${[['all','全部任务'],['active','进行中'],['done','已完成'],['issues','未完成']].map(([key,label])=>`<button class="tab ${taskFilter===key?'active':''}" data-filter="${key}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="task-search" placeholder="搜索任务" aria-label="搜索任务" value="${esc(search)}"></label></div>`+
 (!state.tasks.length?empty('tasks','从一句话开始','描述想完成的工作，路衡会把它拆成可追踪的步骤。',`<button class="primary-button" data-action="new-task">${icon('plus')}发起第一个任务</button>`):`<div class="task-workspace"><div class="task-list">${tasks.length?tasks.map(t=>`<button class="task-card ${String(selectedTaskId)===String(t.id)?'selected':''}" data-task="${esc(t.id)}"><div class="task-card-top">${badge(t.status)}<time>${date(t.createdAt)}</time></div><h3>${esc(t.title||t.prompt)}</h3><span class="task-card-agent">${icon('agents')}${esc(getAgent(t.agentId)?.name||'办公助手')}</span></button>`).join(''):empty('search','没有匹配的任务','试试其他关键词，或切换任务分类。')}</div>${selected?renderTaskDetail(selected):empty('tasks','选择一个任务','点击左侧任务，查看执行步骤与结果。')}</div>`);
}
function renderTaskDetail(t){
 const approvals=pendingApprovals().filter(a=>String(a.taskId)===String(t.id)&&!String(a.type||'').startsWith('local.'));const artifacts=[...new Map([t.artifact,...array(t.artifacts)].map(artifactInfo).filter(Boolean).map(a=>[a.filename,a])).values()];const budget=Math.max(1,Number(t.budget||state.settings.budget||20));const used=Number(t.budgetUsed||0);
 return `<article class="task-detail ${view==='chat'?'chat-turn':''}" data-key="task:${esc(t.id)}"><div class="detail-top"><div class="detail-topline">${badge(t.status)}<div class="button-row">${taskActive(t)?`<button class="secondary-button small-button" data-action="cancel-task" data-id="${esc(t.id)}">${icon('pause')}取消任务</button>`:''}${t.output?`<button class="icon-button" data-action="copy-output" data-id="${esc(t.id)}" aria-label="复制任务结果">${icon('copy')}</button>`:''}</div></div><h2>${esc(t.title||t.prompt)}</h2><div class="detail-meta"><span>${icon('agents')}${esc(getAgent(t.agentId)?.name||'办公助手')}</span><span>${icon('clock')}${date(t.createdAt)}</span><span>预算 ${used} / ${budget} 步</span></div><div class="budget-progress"><i style="width:${Math.min(100,used/budget*100)}%"></i></div></div><div class="detail-body"><h3 class="detail-label request-label">${icon('chat')} ${view==='chat'?'你':'你的需求'}</h3><div class="prompt-block">${esc(t.prompt)}</div>
 ${array(t.steps).length?`<details class="execution-disclosure" data-execution-task="${esc(t.id)}" ${(executionOpen.has(t.id)?executionOpen.get(t.id):view!=='chat')?'open':''}><summary class="detail-label">${icon('chevron')}工具活动 <span>${array(t.steps).length} 个步骤</span></summary><div class="steps">${t.steps.map((s,i)=>`<div class="step ${esc(s.status)}"><span class="step-icon">${['completed','succeeded','done','success'].includes(s.status)?'✓':['failed','error'].includes(s.status)?'!':s.status==='running'?'•':i+1}</span><h4>${esc(s.name||s.title||'执行步骤')}</h4>${s.detail?`<p>${esc(str(s.detail))}</p>`:''}</div>`).join('')}</div></details>`:taskActive(t)?'<div class="compact-empty"><span class="spinner"></span>任务已进入队列，等待开始执行。</div>':''}
 ${approvals.map(a=>a.type==='browser.actions'?`<div class="approval-box" data-key="approval:${esc(a.id)}"><h3>${icon('browser')}网页输入等待完整审批</h3><p>${esc(a.summary)}<br>首次填写或点击前，请核对目标、控件和每个确切输入值。</p><button class="primary-button small-button" data-action="open-controlled-approval" data-id="${esc(a.controlledApprovalId)}">到浏览器工作台审核确切动作</button></div>`:a.type==='mail.send'?`<div class="approval-box" data-key="approval:${esc(a.id)}"><h3>${icon('mail')}真实邮件等待完整审批</h3><p>${esc(str(a.summary))}<br>请到邮件工作台核对全部收件人、服务商、主题和正文后再批准。</p><button class="primary-button small-button" data-action="open-mail-approval" data-id="${esc(a.serviceApprovalId)}">到邮件工作台审核完整内容</button></div>`:`<div class="approval-box" data-key="approval:${esc(a.id)}"><h3>${icon('shield')}需要你的确认</h3><p>${esc(str(a.summary||a.description||'即将执行需要审批的操作，请确认后继续。'))}</p><div class="button-row"><button class="primary-button small-button" data-action="approve" data-id="${esc(a.id)}" ${t.browserSession?.status==='manual'?'disabled title="请先归还浏览器控制权"':''}>${icon('check')}${t.browserSession?.status==='manual'?'请先归还控制权':'确认并继续'}</button><button class="secondary-button small-button" data-action="reject" data-id="${esc(a.id)}">拒绝本次操作</button></div></div>`).join('')}
 ${t.browserSessionId?renderBrowser(t):''}${t.controlledSessionId?`<div class="info-banner">${icon('browser')}此任务拥有一个隔离网页会话。<button class="text-link" data-action="open-controlled-session" data-id="${esc(t.controlledSessionId)}">查看受控浏览器 ↗</button></div>`:''}
 ${t.error?`<div class="approval-box" style="background:#fff5ef;border-color:#ead5c7"><h3>${icon('alert')}任务未完成</h3><p>${esc(str(t.error))}</p>${t.status==='needs_attention'?`<p>请先人工核实${t.controlledSessionId?'网页输入结果':'邮件状态'}；此任务不提供重试。</p>${t.controlledSessionId?`<button class="secondary-button small-button" data-action="open-controlled-session" data-id="${esc(t.controlledSessionId)}">查看网页会话</button>`:''}${t.mailDraftId?`<button class="secondary-button small-button" data-action="open-mail-draft" data-id="${esc(t.mailDraftId)}">查看邮件状态</button>`:''}`:`<button class="secondary-button small-button" data-action="retry-task" data-id="${esc(t.id)}">编辑后重新发起</button>`}</div>`:''}
 ${t.privateReasoning?'<div class="info-banner">模型返回了推理内容，因此本任务正文、推理与结果仅保留本次运行；重启后只显示安全占位，明确生成的文件会保留。</div>':t.localContext?'<div class="info-banner">此角色可使用本机工具，因此本任务正文与结果仅保留本次运行，即使当前本机访问已关闭。重启后只显示安全占位；明确生成或导出的文件会保留。</div>':''}
 ${taskActive(t)&&!t.output?`<div class="chat-running">${icon('spark')}<span>${esc(getAgent(t.agentId)?.name||'路衡')} · ${esc(statuses[t.status]?.[0]||t.status)}</span><button class="text-link" data-action="cancel-task" data-id="${esc(t.id)}">停止</button></div>`:''}
 ${t.output?`<h3 class="detail-label response-label">${icon('spark')}${esc(getAgent(t.agentId)?.name||'路衡')}<span class="response-state">${badge(t.status)}</span></h3><div class="output-block task-result" data-key="output:${esc(t.id)}" data-selection-hold>${formatOutput(t.output)}</div>`:''}
 ${artifacts.map(artifact=>`<a class="file-download" href="${esc(artifact.url)}" download="${esc(artifact.filename)}">${icon('file')}<span>${esc(artifact.name)}<small>下载本地生成的交付文件</small></span>${icon('download','download-icon')}</a>`).join('')}
 ${taskDone(t)?`<div class="chat-output-actions"><button class="icon-button" data-action="copy-output" data-id="${esc(t.id)}" aria-label="复制回复">${icon('copy')}</button>${renderOfficeExports(t)}</div>`:''}
 ${renderTaskMail(t)}
 </div><div class="task-disclaimer"><b>${t.mode==='api'?'API 模式':'演示环境'}</b> · ${t.mode==='api'?'本任务使用创建时配置的模型服务':'旧版演示历史；流程已停用，不能重放'} · ${t.mode==='api'?'真实邮件逐封审批；结果不确定时不重发':'演示邮件仅生成本地草稿'}</div></article>`;
}
function renderTaskMail(t){const mail=array(state.mail?.drafts||state.mail).filter(m=>String(m.taskId)===String(t.id));return mail.map(m=>`<div class="browser-panel"><div class="browser-panel-toolbar">${icon('mail')}本地邮件草稿 <span class="mode-label">未发送</span></div><div style="padding:17px"><h3 class="detail-label">${esc(m.subject||m.title||'邮件草稿')}</h3>${m.to?`<p class="detail-meta">收件人：${esc(str(m.to))}</p>`:''}<div class="output-block" style="margin-bottom:0">${esc(m.body||m.content||'')}</div></div></div>`).join('');}
function renderBrowser(){return `<div class="info-banner">${icon('browser')}这是旧版模拟网页任务的历史记录。内置演示已经移除，旧操作和审批不会执行或重放。<button class="text-link" data-nav="browser">配置真实网页目标 ↗</button></div>`;}

function agentModelLabel(a){return a.modelConfig?.inherit===false?`独立模型 · ${a.modelConfig.model}`:'继承工作台模型';}
function renderAgents(){return pageHeading('YOUR TEAM','懂分工，也懂配合','为每个角色配置模型、做事风格与工具权限。',`<button class="primary-button" data-action="add-agent">${icon('plus')}创建智能体</button>`)+`<div class="info-banner">${icon('shield')}角色可以使用不同的模型与专属知识。这里隔离的是模型检索上下文，不是多用户账户；你仍可管理全部本地资料。</div><div class="cards-grid">${state.agents.map((a,i)=>`<article class="agent-card"><div class="agent-card-header"><div class="agent-avatar color-${i%4}">${esc((a.name||'助').slice(0,1))}</div><div><h3>${esc(a.name)}</h3><span class="agent-role">${esc(a.role||'办公协作助手')}</span></div></div><p>${esc(a.personality||'尚未设置工作风格')}</p><div class="agent-model-label ${a.modelConfig?.inherit===false?'independent':''}">${icon('spark')}<span>${esc(agentModelLabel(a))}</span>${a.modelConfig?.inherit===false?`<small>${a.hasApiKey?'密钥已配置':'需配置密钥'}</small>`:''}</div><div class="permission-tags">${array(a.permissions).map(p=>`<span class="permission-tag">${esc(permissions[p]?.[0]||p)}</span>`).join('')||'<span class="permission-tag">未授予工具权限</span>'}</div><div class="agent-card-footer"><span class="status-text" style="${a.enabled===false?'color:#a8b29d':''}"><i></i>${a.enabled===false?'已停用':'可执行任务'}</span><button class="secondary-button small-button" data-action="edit-agent" data-id="${esc(a.id)}">配置智能体</button></div></article>`).join('')}<button class="create-agent-card" data-action="add-agent">${icon('plus')}<span>添加一位新伙伴</span><small>独立模型、工作风格与工具权限</small></button></div>`;}
function renderKnowledge(){return pageHeading('KNOWLEDGE & MEMORY','把经验，放在合适的位置','共享资料协同使用，角色私有资料按模型检索权限隔离。',`<button class="primary-button" data-action="add-memory">${icon('plus')}添加知识</button>`)+`<div class="info-banner">${icon('knowledge')}你可以查看和管理全部本地知识。「角色私有」仅供所属角色直接检索；读取私有知识后的任务不能再向其他角色转交上下文；可新开只用共享资料的任务。这不是多用户账户权限隔离。</div>`+(state.memories.length?`<div class="cards-grid">${state.memories.map(m=>`<article class="memory-card"><div class="memory-scope ${m.scope==='agent'?'private':''}">${icon(m.scope==='agent'?'lock':'knowledge')}${m.scope==='agent'?`角色私有 · ${esc(getAgent(m.ownerAgentId)?.name||'所属角色')}`:'工作空间共享'}</div><h3>${icon('file')}${esc(m.title||'未命名知识')}</h3><p>${esc(m.content||'')}</p><div class="memory-footer"><span>来源：${esc(m.source||'手动添加')}</span><time>${date(m.createdAt||m.updatedAt)}</time></div></article>`).join('')}</div>`:empty('knowledge','还没有知识资料','添加工作背景或制度要点，并选择共享范围与所属角色。',`<button class="primary-button" data-action="add-memory">${icon('plus')}添加第一条知识</button>`));}
function renderAgentModelForm(a={}){const inherit=a.modelConfig?.inherit!==false;return `<section class="role-model-section"><h3>${icon('spark')}这个角色使用的模型</h3><label class="check-row"><input id="agent-inherit-model" type="checkbox" name="inheritModel" ${inherit?'checked':''}><span>继承工作台的全局模型<small>在 API 模式下生效；不会额外扩大工具权限。</small></span></label><div id="agent-own-model" ${inherit?'hidden':''}><div class="form-field"><label for="agent-endpoint">独立 API 端点</label><input id="agent-endpoint" name="roleEndpoint" type="url" value="${esc(a.modelConfig?.endpoint||state.settings.endpoint||'https://api.openai.com/v1')}" placeholder="https://api.openai.com/v1" ${inherit?'disabled':'required'}><small>仅 HTTPS。任务和该角色有权检索的资料会发送到此服务商。</small></div><div class="form-row"><div class="form-field"><label for="agent-model">模型名称</label><input id="agent-model" name="roleModel" value="${esc(a.modelConfig?.model||'')}" placeholder="服务商支持的模型名称" maxlength="200" ${inherit?'disabled':'required'}></div><div class="form-field"><label for="agent-api-key">此角色的 API Key</label><input id="agent-api-key" name="roleApiKey" type="password" autocomplete="off" placeholder="${a.hasApiKey?'已配置；留空保留当前密钥':'尚未配置独立密钥'}" ${inherit?'disabled':''}><small>留空不会覆盖现有密钥。${credentialStorageHelp()}</small></div></div>${a.hasApiKey?`<label class="check-row"><input type="checkbox" name="clearRoleApiKey" ${inherit?'disabled':''}><span>清除当前角色密钥<small>保存后生效，不影响其他角色。</small></span></label>`:''}<div class="permission-warning">更换服务商域名或恢复全局继承会清除当前角色密钥。读取私有知识后，该任务不能转交其他角色；需要时新开只用共享资料的任务。</div></div></section>`;}
function renderMemoryScopeFields(){return `<div class="form-row"><div class="form-field"><label for="memory-scope">可见范围</label><select id="memory-scope" name="scope"><option value="workspace">工作空间共享</option><option value="agent" ${!state.agents.length?'disabled':''}>仅指定角色使用</option></select></div><div class="form-field" id="memory-owner-field" hidden><label for="memory-owner">所属智能体</label><select id="memory-owner" name="ownerAgentId" disabled>${state.agents.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.role)}</option>`).join('')}</select></div></div><p class="scope-help">共享知识可被获授权角色读取；读取私有知识后的任务不能再向其他角色转交上下文；可新开只用共享资料的任务。你作为本地管理者仍能查看全部内容。</p>`;}

function renderAudit(){return pageHeading('ACTIVITY LOG','看清过程，才能放心托付','任务、审批与配置变更都留有记录，可按时间追溯。',`<button class="secondary-button" data-action="refresh">${icon('refresh')}刷新记录</button>`)+(state.audit.length?`<div class="audit-list">${state.audit.slice(0,150).map(a=>`<article class="audit-item"><div class="audit-symbol">${icon(/approv|批准|拒绝/.test(a.action)?'shield':/agent|智能体/.test(a.action)?'agents':/memory|知识/.test(a.action)?'knowledge':'audit')}</div><div><h3>${esc(auditLabels[a.action]||a.action||a.type||'操作记录')}</h3><p>${esc(str(a.detail||a.message||''))}</p>${a.taskId?`<button class="text-link" data-task="${esc(a.taskId)}">查看关联任务 ↗</button>`:''}</div><time>${date(a.at||a.createdAt,true)}</time></article>`).join('')}</div>`:empty('audit','还没有操作记录','发起任务、添加知识或保存设置后，相应记录会显示在这里。'));}

const weekDays=['日','一','二','三','四','五','六'];
function localTimezone(){return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';}
function scheduleDate(value,timezone){if(!value)return '尚未运行';try{return new Intl.DateTimeFormat('zh-CN',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));}catch{return '时间不可用';}}
function scheduleSummary(schedule){const r=schedule.recurrence||{};if(r.type==='interval')return `每 ${r.intervalMinutes} 分钟`;if(r.type==='weekly')return `每周${array(r.daysOfWeek).map(d=>weekDays[d]).join('、')} ${r.time||''}`;return `每天 ${r.time||''}`;}
function scheduleBadge(status){const values={active:['已启用','completed'],paused:['已暂停','approval'],cancelled:['已取消','cancelled']};const [label,cls]=values[status]||['状态未知','approval'];return `<span class="badge ${cls}">${label}</span>`;}
function renderSchedules(){
 const schedules=array(state.schedules),active=schedules.filter(s=>s.status==='active').length;
 return pageHeading('RECURRING TASKS','把例行工作，排进日程','按明确的时区与频率，持续创建可追踪的本地任务。',`<button class="primary-button" data-action="add-schedule">${icon('plus')}新建周期任务</button>`)+
 `<div class="info-banner schedule-notice">${icon('clock')}<div><strong>本机调度 · ${active} 项已启用</strong>${!heartbeatOn()?'<p class="schedule-heartbeat-warning">主动检查已关闭，周期任务暂不触发。请开启左侧「主动检查」后继续调度。</p>':''}<p>计划会保存在本地，应用或本地服务运行时才会执行。关闭或休眠期间不会执行；恢复后错过的多次执行合并为最多一次，不连续补跑。任务按运行时的工作台模式与角色权限执行；API 模式会发送任务及所需资料到配置的模型服务，可能计费。邮件发送与网页输入仍逐次审批。</p></div></div>`+
 (schedules.length?`<div class="schedule-grid">${schedules.map(s=>{const busy=scheduleBusy.has(s.id),cancelled=s.status==='cancelled';return `<article class="schedule-card" data-schedule-id="${esc(s.id)}"><div class="schedule-top">${scheduleBadge(s.status)}<span>${esc(scheduleSummary(s))}</span></div><h2>${esc(s.title)}</h2><p class="schedule-prompt">${esc(s.prompt)}</p><div class="schedule-meta"><span>${icon('agents')}${esc(getAgent(s.agentId)?.name||'自动选择助手')} · 预算 ${esc(s.budget)} 步</span><span>${icon('clock')}时区 ${esc(s.timezone)}</span></div><dl class="schedule-timing"><dt>下次执行</dt><dd>${s.status==='active'?(s.nextRunAt?esc(scheduleDate(s.nextRunAt,s.timezone)):'等待调度'):s.status==='paused'?'恢复后重新计算':'不再创建任务'}</dd><dt>上次执行</dt><dd>${esc(scheduleDate(s.lastRunAt,s.timezone))}${s.lastTaskId?` <button class="text-link" data-task="${esc(s.lastTaskId)}">查看任务 ↗</button>`:''}</dd></dl>${s.lastError?`<p class="schedule-error">${icon('alert')}${esc(s.lastError)}</p>`:''}<div class="schedule-actions">${!cancelled?`<button class="secondary-button small-button" data-action="edit-schedule" data-id="${esc(s.id)}" ${busy?'disabled':''}>编辑</button><button class="secondary-button small-button" data-action="schedule-${s.status==='paused'?'resume':'pause'}" data-id="${esc(s.id)}" ${busy?'disabled':''}>${icon(s.status==='paused'?'refresh':'pause')}${s.status==='paused'?'恢复':'暂停'}</button><button class="text-link danger-link" data-action="cancel-schedule" data-id="${esc(s.id)}" ${busy?'disabled':''}>取消计划</button>`:'<span class="schedule-closed">记录已保留 · 已创建的任务不受影响</span>'}</div></article>`;}).join('')}</div>`:empty('clock','还没有周期任务','把每天整理资料、每周生成报告这样的例行工作，设置为本地周期任务。',`<button class="primary-button" data-action="add-schedule">${icon('plus')}创建第一个计划</button>`));
}
function renderScheduleForm(schedule){
 const s=schedule||{},r=s.recurrence||{type:'daily',time:'09:00'},timezone=s.timezone||localTimezone();
 const agents=state.agents.filter(a=>a.enabled!==false||a.id===s.agentId);
 return `<p class="modal-subtitle">任务仅在本机应用或服务运行、且主动检查开启时创建。按运行时的工作台模式与角色权限执行；API 模式会自动把任务和所需资料发送到配置的模型服务，可能计费。时间按下面的 IANA 时区解释。</p><form id="schedule-form" data-id="${esc(s.id||'')}"><div class="form-field"><label for="schedule-title">计划名称</label><input id="schedule-title" name="title" required maxlength="200" value="${esc(s.title||'')}" placeholder="例如：每周资料汇总"></div><div class="form-field"><label for="schedule-prompt">每次要执行的任务</label><textarea id="schedule-prompt" name="prompt" required maxlength="12000" placeholder="例如：整理本地工作资料，注明来源并生成报告">${esc(s.prompt||'')}</textarea></div><div class="form-row"><div class="form-field"><label for="schedule-agent">执行智能体</label><select id="schedule-agent" name="agentId"><option value="">默认协调助手</option>${agents.map(a=>`<option value="${esc(a.id)}" ${a.id===s.agentId?'selected':''}>${esc(a.name)}${a.enabled===false?'（已停用，请更换）':''}</option>`).join('')}</select></div><div class="form-field"><label for="schedule-budget">每次执行预算（步骤数）</label><input id="schedule-budget" name="budget" type="number" min="1" max="100" step="1" required value="${Number(s.budget)||Number(state.settings.budget)||20}"></div></div><div class="form-row"><div class="form-field"><label for="schedule-recurrence">执行频率</label><select id="schedule-recurrence" name="recurrenceType"><option value="daily" ${r.type==='daily'?'selected':''}>每天</option><option value="weekly" ${r.type==='weekly'?'selected':''}>每周</option><option value="interval" ${r.type==='interval'?'selected':''}>固定分钟间隔</option></select></div><div class="form-field"><label for="schedule-timezone">IANA 时区</label><input id="schedule-timezone" name="timezone" required maxlength="100" value="${esc(timezone)}" placeholder="例如：Asia/Shanghai" list="schedule-timezones"><datalist id="schedule-timezones"><option value="Asia/Shanghai"><option value="Asia/Hong_Kong"><option value="Asia/Tokyo"><option value="America/New_York"><option value="Europe/London"><option value="UTC"></datalist><small>首次默认此设备时区，可明确修改。</small></div></div><div class="form-field" id="schedule-time-field" ${r.type==='interval'?'hidden':''}><label for="schedule-time">当地执行时间</label><input id="schedule-time" name="time" type="time" value="${esc(r.time||'09:00')}" ${r.type==='interval'?'disabled':'required'}><small>按上方时区的当地时间执行；切换时区不会换算输入值。夏令时跳过不存在的时间，重复时间只执行较早的一次。</small></div><div class="form-field" id="schedule-interval-field" ${r.type!=='interval'?'hidden':''}><label for="schedule-interval">间隔分钟数</label><input id="schedule-interval" name="intervalMinutes" type="number" min="1" max="525600" step="1" value="${Number(r.intervalMinutes)||60}" ${r.type==='interval'?'required':'disabled'}><small>新建计划默认在一个完整间隔后首次执行；编辑时保留原始起点，重新计算下次执行。</small></div><fieldset class="schedule-weekdays" id="schedule-days-field" ${r.type!=='weekly'?'hidden':''}><legend>每周执行日（至少一天）</legend>${[1,2,3,4,5,6,0].map(d=>`<label class="check-row"><input type="checkbox" name="daysOfWeek" value="${d}" ${array(r.daysOfWeek||[1]).includes(d)?'checked':''} ${r.type!=='weekly'?'disabled':''}><span>周${weekDays[d]}</span></label>`).join('')}</fieldset><p class="permission-warning">保存计划即同意按上述周期创建任务及相应的模型调用。邮件发送与网页输入仍逐次审批。错过的执行合并为最多一次；暂停或取消计划不会停止已创建任务，请在任务中心单独处理。</p><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">${s.id?'保存计划':'创建计划'}</button></div></form>`;
}
function syncScheduleFields(){const type=$('#schedule-recurrence')?.value;if(!type)return;for(const [id,enabled] of [['schedule-time-field',type!=='interval'],['schedule-interval-field',type==='interval'],['schedule-days-field',type==='weekly']]){const field=$('#'+id);field.hidden=!enabled;field.querySelectorAll('input').forEach(input=>{input.disabled=!enabled;if(input.type!=='checkbox')input.required=enabled;});}}
async function scheduleAction(name,id,el){if(scheduleBusy.has(id))return;const command=name.replace('schedule-','');if(!['pause','resume','cancel'].includes(command))return;scheduleBusy.add(id);if(el)el.disabled=true;try{await post('/api/schedules/'+encodeURIComponent(id)+'/'+command);if(modal?.kind==='schedule-cancel'&&modal.id===id)closeModal();await loadState(true);toast(command==='pause'?'计划已暂停；已创建的任务保持原状':command==='resume'?'计划已恢复，请核对下次执行时间':'计划已取消；历史任务与记录已保留');}catch(error){const node=$('#modal-root .modal-error');if(node)node.textContent=error.message;toast(error.message,true);}finally{scheduleBusy.delete(id);if(view==='schedules')render(true);if(el&&document.contains(el))el.disabled=false;}}
function renderOfficeExports(task){const owner=getAgent(task.agentId),canExport=owner?.enabled!==false&&array(owner?.permissions).includes('workspace.write');const saved=Object.fromEntries(array(task.exports).filter(a=>['docx','xlsx'].includes(a.format)&&typeof a.url==='string'&&/^\/api\/artifacts\/[^/?#]+$/.test(a.url)).map(a=>[a.format,{url:a.url,name:a.name||a.filename}]));const artifacts={...saved,...officeArtifacts.get(task.id)};return `<section class="office-exports"><h3 class="detail-label">Office 交付文件 </h3><p>根据已完成的任务结果生成本地 Word / Excel 文件；导出不会重新执行任务。</p><div class="button-row">${['docx','xlsx'].map(format=>`<button class="secondary-button small-button" data-action="export-task" data-id="${esc(task.id)}" data-format="${format}" ${!canExport||(task.localContext&&task.liveResultAvailable!==true&&!artifacts[format])||exportBusy.has(task.id+':'+format)?'disabled':''}>${icon('download')}${exportBusy.has(task.id+':'+format)?'正在生成…':format==='docx'?'导出 Word (.docx)':'导出 Excel (.xlsx)'}</button>`).join('')}</div>${task.localContext&&task.liveResultAvailable===false?'<p class="permission-warning">正文已随重启清除，可下载已有文件；不能从占位内容生成新文件。</p>':''}${!canExport?'<p class="permission-warning">执行角色需保持启用且拥有生成文件权限，才能创建新的导出文件。</p>':''}${Object.entries(artifacts).map(([format,a])=>`<a class="office-download" href="${esc(a.url)}" download="${esc(a.name)}">${icon('file')}${esc(a.name)} ${icon('download')}</a>`).join('')}</section>`;}
async function exportTask(id,format){const key=id+':'+format;if(exportBusy.has(key)||!['docx','xlsx'].includes(format))return;exportBusy.add(key);if(view==='tasks'||view==='chat'&&chatTaskId===id)render(true);try{const result=await post('/api/tasks/'+encodeURIComponent(id)+'/export',{format});const a=result.artifact||result;if(typeof a.url!=='string'||!/^\/api\/artifacts\/[^/?#]+$/.test(a.url))throw new Error('导出响应没有可用的本地下载地址');const artifact={url:a.url,name:a.name||a.filename||'任务结果.'+format};officeArtifacts.set(id,{...officeArtifacts.get(id),[format]:artifact});const link=document.createElement('a');link.href=artifact.url;link.download=artifact.name;link.hidden=true;document.body.append(link);link.click();link.remove();toast('已生成 '+format.toUpperCase()+'，可再次点击文件链接下载');}catch(error){toast(error.message,true);}finally{exportBusy.delete(key);if(view==='tasks'||view==='chat'&&chatTaskId===id)render(true);}}
function credentialStorageHelp(){return state.desktop?.available?'默认只保存在当前进程内存中。可在设置下方单独确认，使用系统安全存储保存一份凭据。':'仅保存在服务进程内存中，重启后需重新输入。';}
// UPDATE-CONTROLLER-START
// The updater is main-owned. This panel reads cached status, never checks a
// release on a timer, and never remounts or modifies a settings form.
let desktopUpdateStatus=null,desktopUpdatePolling=false,desktopUpdateBusy=false,desktopUpdateEpoch=0,desktopUpdateError='';
// This unsaved selector is a draft for the next explicit Check, not a setting
// or a subscription. Cached main status must never overwrite the user's choice.
let desktopUpdateChannel='stable';
const updateChannelLabel=channel=>channel==='stable'?'正式版渠道':channel==='preview'?'测试版渠道':'尚未读取渠道';
const UPDATE_ACTIVE_PHASES=new Set(['checking','downloading','verifying','confirming','launching','launch-pending']);
const updateCandidateId=()=>typeof desktopUpdateStatus?.candidate?.id==='string'&&/^[a-f0-9]{32}$/.test(desktopUpdateStatus.candidate.id)?desktopUpdateStatus.candidate.id:null;
function updateSize(bytes){return Number.isSafeInteger(bytes)&&bytes>=0?(bytes/1048576).toFixed(1)+' MiB':'大小待确认';}
function renderUpdateSettings(){
 return `<section class="form-panel update-panel" id="desktop-update-panel" aria-labelledby="desktop-update-heading"><h2 id="desktop-update-heading">${icon('download')}版本与更新</h2><p class="form-panel-description">仅在你点击检查时访问固定 GitHub jobKKB/luheng-highway-agent 发布源；状态刷新只读取客户端缓存。</p><div class="form-field"><label for="update-channel-select">本次检查渠道</label><select id="update-channel-select" aria-describedby="update-channel-warning update-channel-pending"><option value="stable" ${desktopUpdateChannel==='stable'?'selected':''}>正式版（默认）</option><option value="preview" ${desktopUpdateChannel==='preview'?'selected':''}>测试版（包含预发布版本）</option></select><small>只在当前页面会话保留选择，不保存为更新偏好。切换选项不会自动检查或下载。</small></div><p id="update-channel-warning" class="permission-warning">测试版包含未正式发布的版本，可能不稳定。请明确选择测试版后，再点击检查更新。</p><p id="update-channel-pending" class="form-panel-description" hidden></p><div class="security-state">当前版本<span id="update-current-version">正在读取客户端版本…</span></div><div class="security-state">缓存结果渠道<span id="update-channel">尚未读取渠道</span></div><p id="update-status" class="form-status" role="status">正在读取更新状态…</p><div id="update-candidate" hidden><div class="security-state">可用版本<span id="update-version"></span></div><div class="security-state">完整安装包<span id="update-size"></span></div><p id="update-source" class="update-source"></p><p id="update-release-date" class="update-source"></p><p class="permission-warning" id="update-unsigned">安装包未签名。Windows 可能显示安全提示，由你决定是否继续。</p><p class="update-integrity">SHA-256 仅核对下载完整性，不独立认证发布者。</p><p id="update-sha256" class="update-hash"></p><h3 class="detail-label">版本说明（纯文本）</h3><pre id="update-notes" class="update-notes"></pre></div><div id="update-progress-row" hidden><progress id="update-progress" max="100" value="0" aria-label="安装包下载进度"></progress><span id="update-progress-text"></span></div><p id="update-error" class="permission-warning" role="alert" hidden></p><p class="form-panel-description">安装前会显示原生确认窗口。确认后会退出客户端；内存凭据与未保存输入会丢失。请先结束任务、邮件传输、本机操作和受控浏览器会话。不会自动保存凭据。</p><div class="button-row"><button type="button" class="secondary-button" data-action="update-check" id="update-check" disabled>检查更新</button><button type="button" class="primary-button" data-action="update-download" id="update-download" hidden disabled>下载完整安装包</button><button type="button" class="secondary-button" data-action="update-cancel" id="update-cancel" hidden disabled>取消下载</button><button type="button" class="primary-button" data-action="update-install" id="update-install" hidden disabled>请求安装（原生确认）</button></div></section>`;
}
function syncUpdatePanel(){
 const panel=$('#desktop-update-panel');if(!panel)return;
 const status=desktopUpdateStatus,candidate=status?.candidate,phase=status?.phase||'idle',supported=status?.supported===true;
 const text=(selector,value)=>{const node=$(selector);if(node&&node.textContent!==String(value??''))node.textContent=String(value??'');};
 const prop=(selector,key,value)=>{const node=$(selector);if(node&&node[key]!==value)node[key]=value;};
 text('#update-current-version',status?.currentVersion||'尚未读取客户端版本');
 text('#update-channel',updateChannelLabel(status?.channel));
 prop('#update-channel-select','value',desktopUpdateChannel);
 const channelMatches=status?.channel===desktopUpdateChannel;
 const channelPending=!!status&&['stable','preview'].includes(status.channel)&&!channelMatches;
 text('#update-channel-pending',channelPending?'尚未检查所选的'+updateChannelLabel(desktopUpdateChannel)+'；下方为'+updateChannelLabel(status.channel)+'的缓存结果。请点击检查更新后再下载或安装。':'');
 prop('#update-channel-pending','hidden',!channelPending);
 const phaseLabels={unsupported:status?.reason||'仅支持已打包的 Windows x64 当前用户安装；Mac 暂不支持客户端内更新。',idle:'点击检查更新，查看此渠道是否有新版。',checking:'正在检查'+updateChannelLabel(status?.channel)+'发布…',current:'当前版本已是此渠道最新适用版本。',available:'发现新版，请查看来源、版本说明与未签名提示。',downloading:'正在下载完整安装包，可取消。',verifying:'正在核对安装包大小与 SHA-256…',ready:'安装包已核对，点击请求安装后仍需原生确认。',cancelled:'下载已取消，可从头重试。',error:'此次更新操作未完成，请查看原因后重试。',confirming:'请在原生确认窗口决定是否继续安装。',blocked:'尚有任务、外部操作或受控浏览器会话，请结束并关闭浏览器会话后再次请求安装。',launching:'正在准备退出并打开 Windows 安装向导；启动请求不代表安装完成。','launch-pending':'Windows 打开请求尚未结束，请在系统窗口完成或取消；请勿再次启动安装。',updated:'新版本与后端版本已核对。'};
 text('#update-status',!status?'正在读取更新状态…':phaseLabels[phase]||'请查看客户端更新状态。');
 prop('#update-candidate','hidden',!candidate);
 text('#update-version',candidate?.version||'');text('#update-size',updateSize(candidate?.sizeBytes));
 text('#update-source',candidate?'固定来源：GitHub jobKKB/luheng-highway-agent · '+updateChannelLabel(status?.channel)+' · '+String(candidate.releaseUrl||''):'');
 text('#update-release-date',candidate?.releaseDate?'发布日期：'+candidate.releaseDate:'');
 text('#update-sha256',candidate?.sha256?'SHA-256：'+candidate.sha256:'');
 text('#update-notes',candidate?.releaseNotes||'此版本未提供说明。');
 // This implementation ships unsigned packages; do not recast a digest as an
 // identity/signature check even if a future metadata field is incorrect.
 prop('#update-unsigned','hidden',!candidate);
 const downloading=['downloading','verifying'].includes(phase),percent=Math.min(100,Math.max(0,Number(status?.percent)||0));
 prop('#update-progress-row','hidden',!downloading);
 prop('#update-progress','value',percent);
 text('#update-progress-text',percent.toFixed(1)+'% · '+updateSize(status?.bytesReceived)+' / '+updateSize(candidate?.sizeBytes));
 const failure=desktopUpdateError||status?.error?.message||status?.message||'';const retry=Number.isSafeInteger(status?.retryAt)&&status.retryAt>Date.now()?' 可重试时间：'+new Date(status.retryAt).toLocaleString('zh-CN'):'';text('#update-error',failure+retry);prop('#update-error','hidden',!failure);
 const active=UPDATE_ACTIVE_PHASES.has(phase),valid=!!updateCandidateId();
 prop('#update-check','disabled',!supported||desktopUpdateBusy||active);
 text('#update-check',phase==='error'?'重新检查更新':'检查更新');
 const downloadable=supported&&valid&&channelMatches&&['available','cancelled','error'].includes(phase);
 prop('#update-download','hidden',!downloadable);prop('#update-download','disabled',desktopUpdateBusy||!downloadable);
 text('#update-download',['cancelled','error'].includes(phase)?'重试下载（从头下载）':'下载完整安装包');
 prop('#update-cancel','hidden',!downloading);prop('#update-cancel','disabled',desktopUpdateBusy||!downloading);
 const installable=supported&&valid&&channelMatches&&['ready','blocked'].includes(phase);
 prop('#update-install','hidden',!installable);prop('#update-install','disabled',desktopUpdateBusy||!installable);
}
function selectUpdateChannel(value){
 if(!['stable','preview'].includes(value))return;
 desktopUpdateChannel=value;syncUpdatePanel();
}
document.addEventListener('change',event=>{if(event.target.id==='update-channel-select')selectUpdateChannel(event.target.value);});
async function pollDesktopUpdate(){
 if(desktopUpdatePolling||desktopUpdateBusy||!(view==='settings'||['downloading','verifying'].includes(desktopUpdateStatus?.phase)))return;
 desktopUpdatePolling=true;const epoch=desktopUpdateEpoch;
 try{const status=await api('/api/desktop/update');if(epoch===desktopUpdateEpoch){desktopUpdateStatus=status;desktopUpdateError='';syncUpdatePanel();}}
 catch(error){if(epoch===desktopUpdateEpoch){desktopUpdateError=error.message||'更新状态暂不可用';syncUpdatePanel();}}
 finally{desktopUpdatePolling=false;}
}
async function updateAction(name,el){
 if(desktopUpdateBusy||el?.disabled)return;
 const command={'update-check':'check','update-download':'download','update-cancel':'cancel','update-install':'install'}[name];if(!command)return;
 const candidateId=updateCandidateId();if(['download','install'].includes(command)&&(!candidateId||desktopUpdateStatus?.channel!==desktopUpdateChannel)){desktopUpdateError='更新候选已失效，请重新检查。';syncUpdatePanel();return;}
 const input=command==='check'?{channel:desktopUpdateChannel}:['download','install'].includes(command)?{candidateId}:{};
 desktopUpdateBusy=true;desktopUpdateError='';const epoch=++desktopUpdateEpoch;syncUpdatePanel();
 try{const status=await post('/api/desktop/update/'+command,input);if(epoch===desktopUpdateEpoch)desktopUpdateStatus=status;}
 catch(error){if(epoch===desktopUpdateEpoch)desktopUpdateError=error.message||'更新请求未完成，请查看最新状态。';}
 finally{desktopUpdateBusy=false;syncUpdatePanel();}
}
