 $('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭对话框">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;
 document.body.style.overflow='hidden';if(kind==='local-access')syncLocalFormMode();setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),30);
