function closeModal(){const wasOpen=!!modal;if(modal?.kind==='local-full-confirm')localAccessChallenge=null;modal=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(wasOpen){const saved=modalReturnFocus;let target=saved?.node;if(!target?.isConnected){target=[...document.querySelectorAll('[data-action],[data-nav]')].find(node=>(saved?.action?node.dataset.action===saved.action&&node.dataset.id===saved.id:saved?.nav&&node.dataset.nav===saved.nav));}(target||main).focus?.();modalReturnFocus=null;}}
async function loadState(force=false,options={}){
 if(pollBusy){if(!force&&!options.wait)return false;await new Promise(resolve=>refreshWaiters.push(resolve));return loadState(force,options);}pollBusy=true;const settingsEpochAtStart=settingsEpoch;
 try{const data=await api('/api/state');const confirmedSettings=state.settings;state={...state,...data,tasks:array(data.tasks),schedules:array(data.schedules),agents:array(data.agents),memories:array(data.memories),reminders:array(data.reminders),audit:array(data.audit),approvals:array(data.approvals)};if(settingsSaving||settingsEpochAtStart!==settingsEpoch)state.settings=confirmedSettings;await syncLocalAccess(data.localAccess);if(view==='tasks'&&!selectedTaskId&&state.tasks.length)selectedTaskId=state.tasks[0].id;await syncTaskDetail();online=true;const wasLoaded=loaded;loaded=true;const currentLocalSignature=JSON.stringify([localAccessAvailable,state.localAccess]);const localChanged=currentLocalSignature!==localAccessLastSignature;localAccessLastSignature=currentLocalSignature;if(localChanged)chatTurnCache.clear();const activePrompt=document.activeElement?.id==='prompt-input'?{node:document.activeElement,start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null;const sig=JSON.stringify([state,activeTaskDetail],(key,value)=>key==='lastHeartbeat'?undefined:value);if(force||sig!==lastSignature||!wasLoaded){lastSignature=sig;render(force||localChanged&&view==='chat');if(activePrompt&&view==='chat'&&(document.activeElement!==activePrompt.node||!activePrompt.node.isConnected)){$('#prompt-input')?.focus();$('#prompt-input')?.setSelectionRange(activePrompt.start,activePrompt.end);}}else renderChrome();if(localChanged&&view==='settings'&&$('.local-settings-panel'))$('.local-settings-panel').outerHTML=renderLocalSettingsSummary();maybeLocalOnboarding();
 if(modal?.kind==='notifications'&&modal.signature!==notificationSignature()){const scroll=$('#modal-root .modal')?.scrollTop||0;openModal('notifications');const panel=$('#modal-root .modal');if(panel)panel.scrollTop=scroll;}
 for(const r of state.reminders){if(['fired','sent','due'].includes(r.status)&&!notificationSeen.has(r.id)){notificationSeen.add(r.id);if(wasLoaded)toast('提醒：'+r.title);}}
 return true;
 }catch(err){online=false;renderChrome();if(!loaded)render();if(force)toast(err.message||'无法连接本地服务',true);return false;}finally{pollBusy=false;refreshWaiters.splice(0).forEach(resolve=>resolve());if(typeof pollDesktopUpdate==='function')void pollDesktopUpdate();}
}
async function createTask(form){if(submitting)return;const fd=new FormData(form);const prompt=String(fd.get('prompt')||'').trim();if(!prompt||!modelReady()||taskActive(taskById(chatTaskId)||{}))return;const submittedVersion=draftVersion,submittedNavigation=navigationVersion,payload={prompt,agentId:fd.get('agentId')||chosenAgent()?.id||undefined,budget:Number(state.settings.budget)||20,skillIds:[...selectedSkills],...(chatTaskId&&taskDone(taskById(chatTaskId)||{})?{previousTaskId:chatTaskId}:{})},payloadSignature=JSON.stringify(payload);if(!pendingSubmission||pendingSubmission.version!==submittedVersion||pendingSubmission.signature!==payloadSignature)pendingSubmission={id:crypto.randomUUID(),version:submittedVersion,signature:payloadSignature};const submission=pendingSubmission;submitting=true;const button=form.querySelector('button[type="submit"]');button.disabled=true;button.innerHTML='<span class="spinner"></span><span>提交中</span>';
 try{const result=await post('/api/tasks',{...payload,submissionId:submission.id});const task=result.task||result;if(pendingSubmission===submission)pendingSubmission=null;if(draftVersion===submittedVersion)draft='';if(navigationVersion===submittedNavigation)selectedTaskId=task.id;await loadState();if(view==='chat'&&navigationVersion===submittedNavigation){selectActiveChat(task.id);await syncTaskDetail();render(true);const thread=$('.chat-thread');if(thread)thread.scrollTop=thread.scrollHeight;}toast('任务已创建，执行过程会实时更新');}catch(err){toast(err.message,true);}finally{submitting=false;const currentButton=$('#task-form button[type="submit"]');if(currentButton){currentButton.classList.remove('loading-button');currentButton.innerHTML=icon('send');syncComposerButton();}}
}
// SETTINGS-CONTROLLER-START
// Settings drafts and any typed API key exist only in this page's memory; they
// are never written to storage. Edit counters, not values, decide what a late
// save response may replace, so reverting a field to its old saved value or
// retyping the same key after submission is still a newer user edit.
// Each save attempt or connection test claims settingsStatusSeq when it starts;
// a late save refresh only writes status/toast while it still owns that claim.
function savedSettingsValue(field){const s=state.settings||{};if(field==='mode')return 'api';if(field==='endpoint')return s.endpoint||'https://api.openai.com/v1';if(field==='budget')return String(Number(s.budget)||20);return String(s[field]||'');}
function settingsValue(field){return Object.hasOwn(settingsDraft.dirty,field)?settingsDraft.dirty[field]:savedSettingsValue(field);}
function trackSettingsEdit(target){const field=target?.name;if(!field||!Object.hasOwn(settingsDraft.edits,field))return false;if(field==='mode'&&!target.checked)return false;settingsDraft.edits[field]++;if(field==='apiKey')settingsDraft.apiKey=String(target.value??'');else settingsDraft.dirty[field]=String(target.value??'');return true;}
function settingsStatus(text){settingsStatusText=String(text||'');const node=$('#settings-status');if(node)node.textContent=settingsStatusText;}
function applySettingsToForm(form){if(!form)return;for(const field of SETTINGS_FIELDS){if(field==='mode'){for(const radio of form.querySelectorAll('[name="mode"]'))radio.checked=radio.value===settingsValue('mode');continue;}const input=form.querySelector(`[name="${field}"]`);if(input&&input.value!==settingsValue(field))input.value=settingsValue(field);}const key=form.querySelector('[name="apiKey"]');if(key){if(key.value!==settingsDraft.apiKey)key.value=settingsDraft.apiKey;key.placeholder=state.settings?.hasApiKey?'已配置，留空保留当前密钥':'输入模型服务的 API Key';}const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=!!settingsSaving;}
function confirmedSettingsFields(saved){const out={};for(const field of ['mode','endpoint','model','budget','hasApiKey'])if(saved&&Object.hasOwn(saved,field))out[field]=saved[field];return out;}
async function saveSettings(form){
 if(settingsSaving){settingsStatus('上一次保存仍在进行，请等待结果后再保存');return {duplicate:true};}
 const statusSeq=++settingsStatusSeq,ownsStatus=()=>statusSeq===settingsStatusSeq;
 const fd=new FormData(form);const body={mode:'api',endpoint:String(fd.get('endpoint')||'').trim(),model:String(fd.get('model')||'').trim(),budget:Number(fd.get('budget'))};
 if(body.endpoint&&!body.endpoint.startsWith('https://'))throw new Error('模型端点必须使用 HTTPS');
 if(body.mode==='api'&&(!body.endpoint||!body.model))throw new Error('请填写模型端点与模型名称');
 const typedKey=String(fd.get('apiKey')||'').trim();if(typedKey)body.apiKey=typedKey;
 const submittedEdits={...settingsDraft.edits};settingsSaving={epoch:++settingsEpoch};applySettingsToForm(form);settingsStatus('正在保存配置…');
 let saved;
 try{saved=await post('/api/settings',body);}
 catch(err){settingsSaving=null;settingsEpoch++;applySettingsToForm($('#settings-form'));throw err;}
 settingsSaving=null;settingsEpoch++;
 for(const field of SETTINGS_FIELDS)if(settingsDraft.edits[field]===submittedEdits[field])delete settingsDraft.dirty[field];
 if(settingsDraft.edits.apiKey===submittedEdits.apiKey)settingsDraft.apiKey='';
 state.settings={...state.settings,...confirmedSettingsFields(saved)};
 applySettingsToForm($('#settings-form'));if(ownsStatus())settingsStatus('配置已保存，正在刷新工作台状态…');
 const refreshed=await loadState(false,{wait:true});
 if(!ownsStatus())return {saved:true,refreshed,stale:true};
 const message=refreshed?'配置已保存':'配置已保存（本机服务已确认），但刷新工作台状态失败；请稍后刷新查看最新状态';
 settingsStatus(message);toast(message,!refreshed);return {saved:true,refreshed};
}
async function testSettingsConnection(){
 if(settingsSaving){settingsStatus('正在保存配置，保存完成后再测试');return {skipped:true};}
 const seq=++settingsTestSeq,statusSeq=++settingsStatusSeq,epoch=settingsEpoch,s=state.settings||{};let target='未配置模型';
 if(s.mode==='api'){try{target=new URL(s.endpoint).host+' · '+(s.model||'未填写模型');}catch{target='已保存的端点';}}
 const current=()=>seq===settingsTestSeq&&epoch===settingsEpoch&&statusSeq===settingsStatusSeq;
 settingsStatus('正在测试已保存的连接（'+target+'）…');connectionDiagnostic=null;const copyButton=$('[data-action="copy-connection-diagnostic"]');if(copyButton)copyButton.hidden=true;
 let result;
 try{result=await post('/api/settings/test',{},{timeoutMs:45000});}
 catch(err){if(!current())return {stale:true};throw err;}
 if(!current())return {stale:true};
 const text=str(result.message||result.result||result.status||(result.ok===false?'连接测试失败':'连接测试成功'))+'\n测试对象：'+target;
 settingsStatus(text);toast(text,result.ok===false);return {stale:false,result};
}
