document.addEventListener('submit',e=>{if(['task-form','local-access-form','local-full-confirm-form','local-operation-form','agent-form','memory-form','reminder-form','schedule-form','desktop-preferences-form','desktop-credentials-form','settings-form','mail-config-form','mail-draft-form','controlled-target-form','controlled-action-form'].includes(e.target.getAttribute('id'))){e.preventDefault();handleForm(e.target);}});
document.addEventListener('input',e=>{if(e.target.closest?.('#settings-form'))trackSettingsEdit(e.target);if(e.target.id==='prompt-input'){draft=e.target.value;draftVersion++;syncComposerButton();}if(e.target.id==='task-search'){search=e.target.value;const pos=e.target.selectionStart;render(true);const field=$('#task-search');field?.focus();field?.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(['skill-file','skill-package'].includes(e.target.id)){void importSkillFiles(e.target.files);return;}if(e.target.dataset.skillId){const id=e.target.dataset.skillId;if(e.target.checked&&selectedSkills.length>=4){e.target.checked=false;toast('最多启用4个 Skills',true);return;}selectedSkills=e.target.checked?[...selectedSkills,id]:selectedSkills.filter(value=>value!==id);draftVersion++;render();return;}if(e.target.id==='schedule-recurrence')syncScheduleFields();if(e.target.id==='desktop-credential-consent')$('#desktop-save-credentials').disabled=!e.target.checked||!state.desktop?.credentialVault?.available;if(e.target.id==='agent-select'){draftAgent=e.target.value;draftVersion++;syncComposerButton();}if(e.target.id==='agent-inherit-model'){const inherit=e.target.checked;const section=$('#agent-own-model');section.hidden=inherit;section.querySelectorAll('input').forEach(input=>{input.disabled=inherit;if(['agent-endpoint','agent-model'].includes(input.id))input.required=!inherit;});}if(e.target.id==='cb-control'){const option=e.target.selectedOptions[0];const fill=$('#cb-action-type option[value="fill"]');fill.disabled=option.dataset.fillable!=='true';if(fill.disabled&&$('#cb-action-type').value==='fill'){$('#cb-action-type').value='click';$('#cb-value-field').hidden=true;$('#cb-value').disabled=true;}}if(e.target.id==='cb-action-type'){const filling=e.target.value==='fill';$('#cb-value-field').hidden=!filling;$('#cb-value').disabled=!filling;}if(e.target.id==='mail-account-select'){mailAccountId=e.target.value;selectedMailId=null;render(true);}if(e.target.dataset.mailProtocol){const protocol=e.target.dataset.mailProtocol;$('#'+protocol+'-port').value=protocol==='imap'?(e.target.value==='true'?993:143):(e.target.value==='true'?465:587);}if(e.target.id==='memory-scope'){const privateScope=e.target.value==='agent';$('#memory-owner-field').hidden=!privateScope;$('#memory-owner').disabled=!privateScope;$('#memory-owner').required=privateScope;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.body.classList.remove('nav-open');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('new-task');}if(!e.isComposing&&!promptComposing&&(e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.id==='prompt-input'){e.preventDefault();$('#task-form')?.requestSubmit();}if(e.key==='Tab'&&modal){const focusable=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('error',e=>{if(e.target.matches?.('[data-browser-image]')){const replacement=document.createElement('div');replacement.className='browser-unavailable';replacement.textContent='旧版演示画面已移除；历史操作不会重放。';e.target.replaceWith(replacement);}},true);
