/* Local file/command authorization UI. This is an application boundary, not an OS sandbox. */
const localAccessModes = {
 disabled: {label:'本机访问已关闭', short:'本机访问关闭', icon:'lock', description:'不读取外部文件，不执行本机命令'},
 read_only: {label:'只读访问', short:'只读访问', icon:'eye', description:'读取所选目录；不写入文件、不运行命令'},
 confirm: {label:'请求批准', short:'请求批准', icon:'hand', description:'读取所选目录；每次写入与命令都先询问'},
 full: {label:'完全访问权限', short:'完全访问', icon:'alert', description:'文件按所选范围读写；命令无需逐次审批'}
};
let localAccessAvailable=false, localAccessPopoverOpen=false, localAccessOnboardingShown=false;
let localAccessChallenge=null, localAccessLastSignature='', localAccessBusy=false, localManualBusy=false;
const localOperationBusy=new Set(), localOperationResults=new Map();
Object.assign(icons,{
 eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
 hand:'<path d="M8 13V6a2 2 0 0 1 4 0v6-8a2 2 0 0 1 4 0v8-6a2 2 0 0 1 4 0v8c0 5-3 8-7 8h-1c-3 0-5-2-7-5l-2-4a2 2 0 0 1 3-2l2 2Z"/>',
 folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
 terminal:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 9 3 3-3 3m6 0h4"/>'
});
const localAccessState=()=>state.localAccess||{mode:'disabled',configured:false,roots:[],allFiles:false,pending:[],operations:[]};
const localMode=()=>localAccessModes[localAccessState().mode]?localAccessState().mode:'disabled';
const localPending=()=>array(localAccessState().pending).filter(p=>['pending','waiting_approval','awaiting_approval'].includes(p.status||'pending'));
const localOperationKind=o=>String(o.kind||o.type||o.snapshot?.kind||'').replace(/^local\./,'');
const localScopeLabel=s=>s.allFiles?'当前用户可访问的全部文件':array(s.roots).length?`${s.roots.length} 个已选目录`:'尚未选择目录';
const localFolderPickerAvailable=()=>typeof localAccessState().pickerAvailable==='boolean'?localAccessState().pickerAvailable:!!state.desktop?.available;
const localPathExample=()=>localAccessState().platform==='win32'?'C:\\Users\\你的用户名\\Documents\\工作资料':localAccessState().platform==='darwin'?'/Users/你的用户名/Documents/工作资料':'/home/你的用户名/Documents/工作资料';

function renderLocalAccessSelector(){
 const mode=localMode(),info=localAccessModes[mode];
 return `<div class="local-access-selector"><button type="button" id="local-access-toggle" class="local-access-pill ${mode==='full'?'full':''}" data-action="local-toggle" aria-haspopup="menu" aria-expanded="${localAccessPopoverOpen}" aria-controls="local-access-menu" ${!localAccessAvailable?'disabled':''} title="${localAccessAvailable?esc(info.description+' · '+localScopeLabel(localAccessState())):'本机权限服务尚未连接'}">${icon(info.icon)}<span>${localAccessAvailable?info.short:'权限未连接'}</span>${icon('chevron','local-pill-chevron')}</button><div class="local-access-popover" id="local-access-menu" role="menu" aria-label="本机操作审批方式" ${localAccessPopoverOpen?'':'hidden'}><div class="local-popover-heading"><span>如何批准本机操作？</span><button type="button" class="text-link" data-action="local-configure">管理范围</button></div>${Object.entries(localAccessModes).map(([key,item])=>`<button type="button" class="local-mode-row ${key==='full'?'full':''} ${mode===key?'selected':''}" role="menuitemradio" aria-checked="${mode===key}" data-action="local-mode" data-mode="${key}"><span class="local-mode-icon">${icon(item.icon)}</span><span><strong>${item.label}</strong><small>${item.description}</small></span><span class="local-mode-check">${mode===key?icon('check'):''}</span></button>`).join('')}<p class="local-popover-footnote">这是应用内授权。命令使用当前用户权限，未按所选目录隔离。</p></div></div>`;
}
function closeLocalPopover(restoreFocus=false){localAccessPopoverOpen=false;const menu=$('#local-access-menu');if(menu)menu.hidden=true;$('#local-access-toggle')?.setAttribute('aria-expanded','false');if(restoreFocus)$('#local-access-toggle')?.focus();}

function localBoundaryNotes(){
 return `<details class="local-boundary-details"><summary>${icon('shield')}理解权限边界${icon('chevron')}</summary><div><p>此开关控制路衡的本机文件与命令工具，属于应用级授权，不是操作系统沙箱，也不会授予管理员权限。</p><p>文件工具只访问你选择的目录；“全部文件”需要另外明确选择。命令进程使用当前登录用户的权限，可能访问其他文件、网络或启动其他程序，不能保证被限制在这些目录内。</p><p>macOS 的隐私访问、Windows 的系统权限仍由操作系统单独管理。应用不能绕过系统拒绝。</p><p>在 API 模式下，读取到的文件内容与命令输出可能随任务发送给已配置的第三方模型服务。请仅授权适合该服务处理的资料。</p><p>完全访问不会跨程序重启自动恢复，重启后会降为请求批准。</p><p>关闭、降级或修改范围会使旧的待批准操作失效，并停止后续授权；已完成的修改不能撤回，已经启动的命令也可能已产生影响。</p></div></details>`;
}
function renderLocalScopeFields(s,mode){
 return `<details class="local-scope-details" ${mode!=='disabled'?'open':''}><summary>${icon('folder')}文件范围与工具边界${icon('chevron')}</summary><div class="local-scope-body"><div class="form-field"><div class="local-roots-label"><label for="local-roots">允许访问的目录</label>${localFolderPickerAvailable()?`<button type="button" class="text-link" data-action="local-pick-folders">${icon('folder')}选择文件夹</button>`:''}</div><textarea id="local-roots" name="roots" rows="3" spellcheck="false" placeholder="每行一个本机绝对路径，例如：&#10;${esc(localPathExample())}">${esc(array(s.roots).join('\n'))}</textarea><small>只包含此电脑上的目录及其子目录。不要填写网址或文件名；相对路径不会被接受。</small></div><div id="local-all-files-field" ${mode==='full'?'':'hidden'}><label class="check-row local-all-files"><input id="local-all-files" type="checkbox" name="allFiles" ${s.allFiles&&mode==='full'?'checked':''}><span>另外允许访问当前用户可访问的全部文件<small>取消勾选时，文件工具仍仅限上方目录。命令不受这些目录边界隔离。</small></span></label></div><p class="local-tools-summary" id="local-tools-summary">${esc(localAccessModes[mode]?.description||'')}</p></div></details>`;
}
function renderLocalAccessForm(preferredMode){
 const s=localAccessState(),onboarding=!s.configured,mode=localAccessModes[preferredMode]?preferredMode:localMode();
 return `<div class="local-modal-intro"><span class="local-intro-symbol">${icon('shield')}</span><div><strong>${onboarding?'让路衡帮忙处理本机资料':'你的电脑，你来授权'}</strong><p>${onboarding?'默认关闭。选好权限和目录后才会启用，也可以稍后再设置。':'调整后立即生效；提高到完全访问还需要再次确认。'}</p></div></div><form id="local-access-form" data-onboarding="${onboarding}"><fieldset class="local-mode-options"><legend>选择一种审批方式</legend>${Object.entries(localAccessModes).map(([key,item])=>`<label class="local-mode-option ${key==='full'?'full':''}"><input type="radio" name="localMode" value="${key}" ${mode===key?'checked':''}><span class="local-mode-icon">${icon(item.icon)}</span><span><strong>${item.label}</strong><small>${item.description}</small></span></label>`).join('')}</fieldset>${renderLocalScopeFields(s,mode)}${localBoundaryNotes()}<div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="${onboarding?'local-defer':'close-modal'}">${onboarding?'稍后设置':'取消'}</button><button type="submit" class="primary-button" id="local-save-button">${mode==='full'?'继续确认完全访问':'保存权限'}</button></div></form>${onboarding?'':renderLocalManualTools()}`;
}
function renderLocalFullConfirmation(){
 const request=localAccessChallenge;if(!request)return '<p class="modal-subtitle">确认已失效，请关闭后重新设置。</p>';
 const scopes=request.allFiles?'当前登录用户可访问的全部文件':array(request.roots).join('\n');
 return `<div class="local-full-warning">${icon('alert')}<div><strong>允许无需逐次审批的本机操作？</strong><p>路衡可以修改或删除授权范围内的文件，并执行本机命令。命令以当前用户权限运行，可能访问范围外的文件、联网或启动其他程序。</p></div></div><div class="local-confirm-scope"><span>此次文件范围</span><pre>${esc(scopes)}</pre><span>命令权限</span><p>当前登录用户权限；应用不提供操作系统级的目录隔离</p></div>${request.summary?`<p class="modal-subtitle">${esc(str(request.summary))}</p>`:''}<p class="modal-subtitle">这不会授予管理员权限，也不会替你接受系统隐私授权。API 模式下，读取内容与输出可能发送至已配置的模型服务。你可以随时在输入框旁关闭访问。</p><form id="local-full-confirm-form"><label class="check-row local-full-consent"><input name="riskUnderstood" type="checkbox" required><span>我理解本机完全访问风险<small>我同意上述文件范围与命令权限，并允许它们无需逐次审批。</small></span></label><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="local-back">返回修改</button><button type="submit" class="primary-button local-full-button">确认开启完全访问</button></div></form>`;
}
function renderLocalManualTools(){
 const mode=localMode(),roots=array(localAccessState().roots),disabled=mode==='disabled';
 return `<details class="local-manual-tools"><summary>${icon('terminal')}本机工具与操作验证${icon('chevron')}</summary><p>准备一个明确操作。请求批准模式下，写入与命令会先出现在对话里，等待你逐次确认。</p><form id="local-operation-form"><div class="form-field"><label for="local-operation-kind">操作类型</label><select id="local-operation-kind" name="kind" ${disabled?'disabled':''}><option value="list">列出目录</option><option value="read">读取文件</option><option value="write" ${mode==='read_only'?'disabled':''}>写入文件（完整替换）</option><option value="command" ${mode==='read_only'?'disabled':''}>执行命令</option></select></div><div class="form-field" id="local-operation-path-field"><label for="local-operation-path">绝对路径</label><input id="local-operation-path" name="path" spellcheck="false" value="${esc(roots[0]||'')}" placeholder="输入允许范围内的绝对路径" ${disabled?'disabled':''} required></div><div class="form-field" id="local-operation-content-field" hidden><label for="local-operation-content">完整文件内容</label><textarea id="local-operation-content" name="content" rows="4" disabled></textarea><small>会替换文件的全部内容，请先自行保留需要的副本。不要填写密钥或密码。</small></div><div id="local-operation-command-fields" hidden><div class="form-field"><label for="local-executable">可执行程序</label><input id="local-executable" name="executable" placeholder="例如：/usr/bin/node 或 C:\\Windows\\System32\\cmd.exe" spellcheck="false" disabled></div><div class="form-field"><label for="local-command-args">参数（JSON 数组）</label><textarea id="local-command-args" name="args" rows="2" placeholder='["-e", "console.log(1)"]' spellcheck="false" disabled>[]</textarea><small>程序必须填写本机绝对路径。每项是一个完整参数；不会由前端拼接成 shell 命令。</small></div><div class="form-field"><label for="local-command-cwd">工作目录（绝对路径）</label><input id="local-command-cwd" name="cwd" value="${esc(roots[0]||'')}" spellcheck="false" disabled></div><p class="permission-warning">命令进程未按文件目录隔离，请只提交你理解的命令；不要输入凭据。</p></div>${disabled?'<p class="modal-subtitle">本机访问当前关闭。先保存所需权限后才能使用。</p>':''}<div class="modal-error" role="alert"></div><button type="submit" class="secondary-button" ${disabled?'disabled':''}>${icon('arrow')}准备此操作</button></form></details>`;
}
function localStatusLabel(status){return ({pending:'等待你确认',waiting_approval:'等待你确认',running:'正在执行',executing:'正在执行',completed:'已完成',succeeded:'已完成',done:'已完成',approved:'已批准',rejected:'已拒绝',revoked:'授权已撤回',cancelled:'已取消',expired:'已过期',stale:'审批已失效',invalidated:'审批已失效',interrupted:'已中断',failed:'执行失败',unknown:'结果需核实'})[status]||status||'已记录';}
function renderLocalOperationSnapshot(operation){
 const snapshot=operation.snapshot||operation,kind=localOperationKind(operation);
 if(kind==='command')return `<dl class="local-operation-snapshot"><dt>程序</dt><dd>${esc(snapshot.executable||'未提供')}</dd><dt>完整参数</dt><dd><pre>${esc(JSON.stringify(array(snapshot.args),null,2))}</pre></dd><dt>工作目录</dt><dd>${esc(snapshot.cwd||'未提供')}</dd><dt>超时上限</dt><dd>${snapshot.timeoutMs?esc(Number(snapshot.timeoutMs)/1000)+' 秒':'由服务端限制'}</dd></dl><p class="local-command-boundary">${icon('alert')}命令以当前用户权限运行；未按所选目录隔离</p>`;
 if(kind==='write')return `<dl class="local-operation-snapshot"><dt>目标文件</dt><dd>${esc(snapshot.path||'未提供')}</dd><dt>写入方式</dt><dd>完整替换文件内容</dd></dl><details class="local-write-content" open><summary>此次写入的完整内容</summary><pre>${esc(snapshot.content??'')}</pre></details>${snapshot.contentDigest?`<p class="local-operation-digest">内容摘要：${esc(snapshot.contentDigest)}</p>`:''}`;
 return `<p class="local-operation-path">${esc(snapshot.path||operation.path||'')}</p>`;
}
function renderLocalConversation(){
 if(!localAccessAvailable)return '';
 const pending=localPending(),pendingIds=new Set(pending.map(p=>p.id));
 const history=array(localAccessState().operations).filter(o=>!pendingIds.has(o.id)).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,4);
 if(!pending.length&&!history.length)return '';
 return `<section class="local-conversation" data-key="local-conversation" aria-label="本机操作与审批" aria-live="polite">${pending.map(o=>{const kind=localOperationKind(o),busy=localOperationBusy.has(o.id);return `<article class="local-approval-card" data-local-operation="${esc(o.id)}" data-key="local-op:${esc(o.id)}"><div class="local-operation-heading"><span>${icon(kind==='command'?'terminal':'file')}<strong>${kind==='command'?'执行本机命令':'写入本机文件'}</strong></span><span class="badge approval">等待你确认</span></div><p class="local-operation-summary">${esc(o.summary||'请审核这一次操作的确切内容。')}</p>${renderLocalOperationSnapshot(o)}<p class="local-approval-note">只批准这一次。内容、路径或权限范围改变后需重新请求。</p><div class="button-row"><button class="primary-button small-button" data-action="local-approve" data-id="${esc(o.id)}" ${busy||!online?'disabled':''}>${busy?'<span class="spinner"></span>处理中':'批准这一次'}</button><button class="secondary-button small-button" data-action="local-reject" data-id="${esc(o.id)}" ${busy||!online?'disabled':''}>拒绝本次操作</button></div></article>`;}).join('')}${history.map(o=>{const result=localOperationResults.get(o.id),kind=localOperationKind(o);return `<article class="local-operation-record" data-key="local-record:${esc(o.id)}"><div class="local-operation-heading"><span>${icon(kind==='command'?'terminal':kind==='list'?'folder':'file')}<strong>${esc(({list:'列出本机目录',read:'读取本机文件',write:'写入本机文件',command:'执行本机命令'})[kind]||o.summary||'本机操作')}</strong></span><span class="local-record-status ${['failed','unknown'].includes(o.status)?'issue':''}">${esc(localStatusLabel(o.status))}</span></div>${o.path||o.snapshot?.path?`<p class="local-operation-path">${esc(o.path||o.snapshot.path)}</p>`:''}${o.error?`<p class="local-operation-error">${esc(o.error)}</p>`:''}${result!==undefined?`<details class="local-operation-result"><summary>查看本次输出</summary><pre>${esc(str(result))}</pre><small>输出仅在当前页面显示，请谨慎分享。</small></details>`:''}</article>`;}).join('')}</section>`;
}
function renderLocalSettingsSummary(){
 const s=localAccessState(),mode=localMode();
 return `<section class="form-panel local-settings-panel"><h2>${icon('shield')}本机访问权限</h2><div class="local-settings-status"><span class="local-access-pill ${mode==='full'?'full':''}">${icon(localAccessModes[mode].icon)}${localAccessAvailable?localAccessModes[mode].label:'权限服务未连接'}</span><span>${esc(localScopeLabel(s))}</span></div><p class="form-panel-description">${localAccessModes[mode].description}。这是应用级授权；命令进程不是目录隔离沙箱。</p><div class="button-row"><button type="button" class="secondary-button" data-action="local-configure" ${!localAccessAvailable?'disabled':''}>管理权限与范围</button>${mode!=='disabled'?'<button type="button" class="danger-link" data-action="local-revoke">立即关闭访问</button>':''}</div></section>`;
}

async function syncLocalAccess(provided){
 try{const response=provided&&!provided.summariesOnly?provided:await api('/api/local-access/state');const next=response.localAccess||response.state?.localAccess||response;if(!localAccessModes[next.mode])throw new Error('权限状态暂不可用');state.localAccess={...next,pending:array(next.pending),operations:array(next.operations)};localAccessAvailable=true;}catch{localAccessAvailable=false;closeLocalPopover();}
}
function maybeLocalOnboarding(){if(localAccessAvailable&&!localAccessState().configured&&!localAccessOnboardingShown&&!modal){localAccessOnboardingShown=true;openModal('local-access','disabled');}}
function rememberLocalResult(response){
 const operation=response.operation||response.pending?.operation||response.pending;if(operation?.id&&response.result!==undefined)localOperationResults.set(operation.id,response.result);
 while(localOperationResults.size>12)localOperationResults.delete(localOperationResults.keys().next().value);
}
async function refreshLocalAccess(force=true){await syncLocalAccess();await loadState(force);}
async function saveLocalAccess(body){await post('/api/local-access/configure',{...body,onboardingComplete:true});localAccessChallenge=null;await refreshLocalAccess();}
function localPaths(value){return [...new Set(String(value||'').split(/\r?\n/).map(p=>p.trim()).filter(Boolean))];}
function validateLocalPaths(roots){if(roots.some(p=>!p.startsWith('/')&&!/^[A-Za-z]:[\\/]/.test(p)&&!/^\\\\[^\\]+\\[^\\]+/.test(p)))throw new Error('请填写本机绝对目录路径；每行一个，不支持相对路径。');}
function syncLocalFormMode(){
 const selected=$('#local-access-form input[name="localMode"]:checked')?.value||'disabled';
 const field=$('#local-all-files-field');if(field)field.hidden=selected!=='full';
 if(selected!=='full'&&$('#local-all-files'))$('#local-all-files').checked=false;
 const summary=$('#local-tools-summary');if(summary)summary.textContent=localAccessModes[selected].description;
 const roots=$('#local-roots');if(roots)roots.disabled=selected==='disabled'||!!$('#local-all-files')?.checked;
 if(selected!=='disabled'&&$('.local-scope-details'))$('.local-scope-details').open=true;
 const save=$('#local-save-button');if(save)save.textContent=selected==='full'?'继续确认完全访问':'保存权限';
}
function syncLocalOperationFields(){
 const kind=$('#local-operation-kind')?.value;for(const [selector,enabled] of [['#local-operation-path-field',kind!=='command'],['#local-operation-content-field',kind==='write'],['#local-operation-command-fields',kind==='command']]){const section=$(selector);if(!section)continue;section.hidden=!enabled;section.querySelectorAll('input,textarea').forEach(input=>{input.disabled=!enabled;input.required=enabled&&input.name!=='content';});}
}
async function handleLocalForm(form){
 const manualOperation=form.id==='local-operation-form';if(manualOperation?localManualBusy:localAccessBusy)return;if(manualOperation)localManualBusy=true;else localAccessBusy=true;const submit=form.querySelector('[type="submit"]'),error=form.querySelector('.modal-error');if(submit)submit.disabled=true;if(error)error.textContent='';const fd=new FormData(form);
 try{
  if(form.id==='local-access-form'){
   const mode=String(fd.get('localMode')||'disabled'),allFiles=mode==='full'&&fd.has('allFiles'),roots=mode==='disabled'||allFiles?[]:localPaths(fd.get('roots'));
   validateLocalPaths(roots);if(mode!=='disabled'&&!allFiles&&!roots.length)throw new Error('请至少填写一个允许访问的目录。');
   if(mode==='full'){
    const result=await post('/api/local-access/full-access-request',{roots,allFiles});
    if(!result.challenge)throw new Error('服务未返回有效的确认凭证，请稍后再试。');
    if(!document.contains(form)||modal?.kind!=='local-access')return;
    localAccessChallenge={...result,roots,allFiles};openModal('local-full-confirm');
   }else{await saveLocalAccess({mode,roots,allFiles:false});if(document.contains(form))closeModal();toast(mode==='disabled'?'本机访问已关闭，旧审批已失效':'本机权限已保存，旧审批已失效');}
  }
  if(form.id==='local-full-confirm-form'){
   if(!fd.has('riskUnderstood'))throw new Error('请先确认你理解这些风险。');const request=localAccessChallenge;if(!request)throw new Error('确认凭证已失效，请返回重新设置。');
   if(request.expiresAt&&new Date(request.expiresAt).getTime()<=Date.now())throw new Error('此次确认已过期，请返回重新设置。');
   await saveLocalAccess({mode:'full',roots:request.roots,allFiles:request.allFiles,challenge:request.challenge,confirmation:'我理解本机完全访问风险'});if(document.contains(form))closeModal();toast('完全访问已开启，可在输入框旁随时关闭');
  }
  if(form.id==='local-operation-form'){
   const kind=String(fd.get('kind')),body={kind};if(kind==='command'){let args;try{args=JSON.parse(String(fd.get('args')||'[]'));}catch{throw new Error('命令参数必须是有效的 JSON 数组。');}if(!Array.isArray(args)||args.some(v=>typeof v!=='string'))throw new Error('命令参数数组的每一项都必须是字符串。');body.executable=String(fd.get('executable')||'').trim();validateLocalPaths([body.executable]);body.args=args;body.cwd=String(fd.get('cwd')||'').trim();validateLocalPaths([body.cwd]);if(!body.executable||!body.cwd)throw new Error('请填写可执行程序和绝对工作目录。');}else{body.path=String(fd.get('path')||'').trim();if(!body.path)throw new Error('请填写目标绝对路径。');validateLocalPaths([body.path]);if(kind==='write')body.content=String(fd.get('content')||'');}
   const result=await post('/api/local-access/operations',body,{timeoutMs:90000});rememberLocalResult(result);await refreshLocalAccess();if(document.contains(form)){closeModal();navigate('chat');}toast(result.pending?'已准备操作，请在对话中批准这一次':'本机操作状态已更新，请查看对话');
  }
 }catch(err){if(error&&document.contains(error))error.textContent=err.message;else toast(err.message,true);}finally{if(manualOperation)localManualBusy=false;else localAccessBusy=false;if(submit&&document.contains(submit))submit.disabled=false;}
}
async function localAccessAction(name,el){
 const id=el?.dataset.id;
 if(name==='local-toggle'){localAccessPopoverOpen=!localAccessPopoverOpen;$('#local-access-menu').hidden=!localAccessPopoverOpen;el.setAttribute('aria-expanded',String(localAccessPopoverOpen));if(localAccessPopoverOpen)$('#local-access-menu [aria-checked="true"]')?.focus();return;}
 if(name==='local-pick-folders'){if(localAccessBusy)return;localAccessBusy=true;el.disabled=true;try{const result=await post('/api/local-access/select-folders',{},{timeoutMs:130000});if(!result.cancelled&&document.contains(el)){const field=$('#local-roots');if(field)field.value=[...new Set([...localPaths(field.value),...array(result.paths)])].join('\n');syncLocalFormMode();}}catch(err){const error=$('#modal-root .modal-error');if(error)error.textContent=err.message;else toast(err.message,true);}finally{localAccessBusy=false;if(document.contains(el))el.disabled=false;}return;}
 if(name==='local-review'){closeModal();navigate('chat');setTimeout(()=>document.querySelector('[data-local-operation="'+CSS.escape(id)+'"]')?.scrollIntoView({block:'center',behavior:'smooth'}),0);return;}
 if(name==='local-configure'){closeLocalPopover();openModal('local-access');return;}
 if(name==='local-back'){const s=localAccessChallenge;localAccessChallenge=null;openModal('local-access','full');if(s){$('#local-roots').value=s.roots.join('\n');$('#local-all-files').checked=s.allFiles;syncLocalFormMode();}return;}
 if(localAccessBusy||localOperationBusy.has(id)||el?.disabled)return;
 if(name==='local-approve'||name==='local-reject'){
  const operation=localPending().find(o=>o.id===id);if(!operation){toast('此审批已失效，请查看最新状态',true);await refreshLocalAccess();return;}
  localOperationBusy.add(id);el.disabled=true;const card=el.closest('.local-approval-card');card?.querySelectorAll('button').forEach(b=>b.disabled=true);
  try{const result=await post('/api/local-access/operations/'+encodeURIComponent(id)+(name==='local-approve'?'/approve':'/reject'),{digest:operation.digest},{timeoutMs:120000});rememberLocalResult(result);await refreshLocalAccess();toast(name==='local-reject'?'已拒绝本次操作':'此次批准已使用，请核对执行结果');}catch(err){toast(err.message,true);await refreshLocalAccess();}finally{localOperationBusy.delete(id);if(view==='chat')render(true);}return;
 }
 const mode=el?.dataset.mode;closeLocalPopover();
 if(name==='local-mode'&&mode===localMode())return;
 if(name==='local-mode'&&mode==='full'){openModal('local-access','full');return;}
 if(name==='local-mode'&&mode!=='disabled'&&(!localAccessState().configured||!array(localAccessState().roots).length||localAccessState().allFiles)){openModal('local-access',mode);return;}
 localAccessBusy=true;if(el)el.disabled=true;
 try{
  if(name==='local-defer'){await saveLocalAccess({mode:'disabled',roots:[],allFiles:false});if(modal?.kind==='local-access')closeModal();toast('本机访问保持关闭；需要时可从输入框旁设置');}
  else if(name==='local-revoke'||name==='local-mode'&&mode==='disabled'){await post('/api/local-access/revoke',{});await refreshLocalAccess();toast('本机访问已立即关闭，旧审批已失效');}
  else if(name==='local-mode'&&localAccessModes[mode]){await saveLocalAccess({mode,roots:array(localAccessState().roots),allFiles:false});toast(`已切换为${localAccessModes[mode].label}，旧审批已失效`);}
 }catch(err){const error=$('#modal-root .modal-error');if(error)error.textContent=err.message;toast(err.message,true);}finally{localAccessBusy=false;if(el&&document.contains(el))el.disabled=false;}
}

document.addEventListener('click',e=>{if(!e.target.closest('.local-access-selector'))closeLocalPopover();});
document.addEventListener('change',e=>{if(e.target.name==='localMode'||e.target.id==='local-all-files')syncLocalFormMode();if(e.target.id==='local-operation-kind')syncLocalOperationFields();});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&localAccessPopoverOpen){e.preventDefault();closeLocalPopover(true);}
 const row=e.target.closest?.('#local-access-menu [role="menuitemradio"]');if(row&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const rows=[...$('#local-access-menu').querySelectorAll('[role="menuitemradio"]')],index=rows.indexOf(row);rows[e.key==='Home'?0:e.key==='End'?rows.length-1:(index+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length].focus();}
});

renderChrome();loadState();setInterval(()=>loadState(),2000);
